package com.rpsbattle.worker.remote;

import com.rpsbattle.auth.AuthException;
import com.rpsbattle.tournament.registry.TournamentRegistry;
import com.rpsbattle.tournament.coding.SubmissionStore;
import com.rpsbattle.tournament.domain.*;
import java.time.*;
import java.util.*;
import java.sql.ResultSet;
import java.sql.SQLException;
import org.springframework.jdbc.core.JdbcTemplate;
import org.springframework.stereotype.Service;
import org.springframework.transaction.annotation.*;

/** Admin-only bounded responses. One metadata snapshot, no source, credential or per-worker DB queries. */
@Service
public class WorkerOperationsService {
 private final JdbcTemplate db;private final Clock clock;private final WorkerGroupService groups;private final RemoteRoutingService routing;private final TournamentRegistry tournaments;private final SubmissionStore submissions;
 public WorkerOperationsService(JdbcTemplate db,Clock clock,WorkerGroupService groups,RemoteRoutingService routing,TournamentRegistry tournaments,SubmissionStore submissions){this.db=db;this.clock=clock;this.groups=groups;this.routing=routing;this.tournaments=tournaments;this.submissions=submissions;}
 @org.springframework.beans.factory.annotation.Value("${rps.worker.ops-cpu-warning:90}") double cpuWarning=90;
 @org.springframework.beans.factory.annotation.Value("${rps.worker.ops-memory-warning:90}") double memoryWarning=90;
 @org.springframework.beans.factory.annotation.Value("${rps.worker.ops-disk-warning-mb:1024}") long diskWarning=1024;
 public record Row(WorkerTelemetryService.View worker,List<UUID> groups,List<String> warnings){}
 public record Page(List<Row> items,long total,int page,int size,Map<String,Long> summary,Map<String,Long> attention,Instant serverNow){}
 static Instant instant(ResultSet r,String key)throws SQLException{var t=r.getTimestamp(key);return t==null?null:t.toInstant();}
 static Double number(ResultSet r,String key)throws SQLException{var n=(Number)r.getObject(key);return n==null?null:n.doubleValue();}
 private List<WorkerTelemetryService.View> snapshot(){
  Instant now=clock.instant();
  return db.query("select w.*,c.cpu_cores,c.memory_mb,c.os,c.docker_enabled,c.supported_languages,c.max_concurrent_matches,c.max_bot_processes,h.sequence_number,h.heartbeat_epoch sample_epoch,h.active_matches,h.offered_slots,h.active_bot_processes,h.cpu_usage,h.memory_usage,h.disk_free_mb,h.cache_size_mb,h.cache_hits,h.cache_misses,l.max_matches admin_limit,(select count(*) from match_execution_attempts a where a.worker_id=w.id and a.active_marker=1) reserved,exists(select 1 from worker_credentials k where k.worker_id=w.id and k.revoked_at is not null) revoked from workers w left join worker_capabilities c on c.worker_id=w.id left join worker_heartbeats h on h.worker_id=w.id left join worker_capacity_limits l on l.worker_id=w.id",(r,n)->{
   UUID id=r.getObject("id",UUID.class);Instant last=instant(r,"last_heartbeat_at");String status=WorkerTelemetryService.statusAt(r.getString("status"),last,instant(r,"registered_at"),now);
   var base=new WorkerTelemetryService.View(id,r.getString("name"),status,r.getString("approval_status"),r.getString("trust_level"),r.getLong("revision"),r.getString("remote_address"),r.getString("worker_version"),r.getInt("protocol_version"),last,null,null,0,0,false,null,0);
   WorkerTelemetryService.Capabilities c=r.getObject("cpu_cores")==null?null:new WorkerTelemetryService.Capabilities(r.getInt("cpu_cores"),r.getLong("memory_mb"),r.getString("os"),r.getBoolean("docker_enabled"),r.getString("supported_languages").isEmpty()?Set.of():Set.of(r.getString("supported_languages").split(",")),r.getInt("max_concurrent_matches"),r.getInt("max_bot_processes"),null,1);
   WorkerTelemetryService.Heartbeat h=r.getObject("sequence_number")==null?null:new WorkerTelemetryService.Heartbeat(r.getLong("sample_epoch"),r.getLong("sequence_number"),r.getInt("active_matches"),r.getInt("offered_slots"),r.getInt("active_bot_processes"),number(r,"cpu_usage"),number(r,"memory_usage"),r.getLong("disk_free_mb"),r.getLong("cache_size_mb"),r.getLong("cache_hits"),r.getLong("cache_misses"));
   return WorkerTelemetryService.project(base,c,h,r.getBoolean("revoked"),r.getObject("admin_limit")==null?null:r.getInt("admin_limit"),r.getInt("reserved"));
  });
 }
 private List<String> warnings(WorkerTelemetryService.View w){var list=new ArrayList<String>();if(w.status().equals("OFFLINE"))list.add("OFFLINE");if(!w.status().equals("DISABLED")&&!w.credentialRevoked()&&(w.lastHeartbeatAt()==null||!clock.instant().isBefore(w.lastHeartbeatAt().plusSeconds(30))))list.add("STALE");var h=w.heartbeat();if(h!=null&&!w.status().equals("DISABLED")&&!w.credentialRevoked()){if(h.cpuUsage()!=null&&h.cpuUsage()>=cpuWarning)list.add("CPU_HIGH");if(h.memoryUsage()!=null&&h.memoryUsage()>=memoryWarning)list.add("RAM_HIGH");if(h.diskFreeMb()<diskWarning)list.add("DISK_LOW");}if(w.status().equals("DEGRADED"))list.add("DEGRADED");if(w.approvalStatus().equals("PENDING_APPROVAL"))list.add("PENDING_APPROVAL");return list;}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public Page workers(int page,int size,String search,String status,String trust,UUID group,String sort){
  if(page<0||page>100000||!Set.of(25,50,100).contains(size)||search.length()>100||!Set.of("","ONLINE","BUSY","OFFLINE","DISABLED","DRAINING","DRAINED","DEGRADED","STARTING","STALE","CPU_HIGH","RAM_HIGH","DISK_LOW","PENDING_APPROVAL").contains(status)||!Set.of("","TRUSTED","COMMUNITY","UNTRUSTED").contains(trust))throw new AuthException("INVALID_FILTER",400);
  var all=snapshot();Map<UUID,List<UUID>> membership=new HashMap<>();db.query("select worker_id,group_id from worker_group_members",r->{membership.computeIfAbsent(r.getObject(1,UUID.class),k->new ArrayList<>()).add(r.getObject(2,UUID.class));});
  var summary=new LinkedHashMap<String,Long>();for(String key:List.of("total","online","offline","disabled","draining","degraded","freeSlots","activeMatches"))summary.put(key,0L);var attention=new LinkedHashMap<String,Long>();
  var rows=new ArrayList<Row>();for(var w:all){summary.merge("total",1L,Long::sum);String key=switch(w.status()){case "ONLINE","BUSY"->"online";case "DRAINING","DRAINED"->"draining";default->w.status().toLowerCase(Locale.ROOT);};if(summary.containsKey(key))summary.merge(key,1L,Long::sum);summary.merge("freeSlots",(long)(w.credentialRevoked()?0:w.effectiveFreeSlots()),Long::sum);summary.merge("activeMatches",(long)w.reservedSlots(),Long::sum);var flags=warnings(w);flags.forEach(f->attention.merge(f,1L,Long::sum));rows.add(new Row(w,membership.getOrDefault(w.id(),List.of()),flags));}
  Comparator<Row> order=switch(sort){case "name"->Comparator.comparing(r->r.worker().name(),String.CASE_INSENSITIVE_ORDER);case "cpu"->Comparator.comparingDouble((Row r)->r.worker().heartbeat()==null||r.worker().heartbeat().cpuUsage()==null?-1:r.worker().heartbeat().cpuUsage()).reversed();case "ram"->Comparator.comparingDouble((Row r)->r.worker().heartbeat()==null||r.worker().heartbeat().memoryUsage()==null?-1:r.worker().heartbeat().memoryUsage()).reversed();case "slots"->Comparator.comparingInt((Row r)->r.worker().effectiveFreeSlots()).reversed();case "heartbeat"->Comparator.comparing((Row r)->r.worker().lastHeartbeatAt(),Comparator.nullsFirst(Comparator.naturalOrder()));case "status"->Comparator.comparing(r->r.worker().status());default->throw new AuthException("INVALID_FILTER",400);};
  String q=search.strip().toLowerCase(Locale.ROOT);var filtered=rows.stream().filter(r->r.worker().name().toLowerCase(Locale.ROOT).contains(q)&&(status.isEmpty()||r.worker().status().equals(status)||r.warnings().contains(status))&&(trust.isEmpty()||r.worker().trustLevel().equals(trust))&&(group==null||r.groups().contains(group))).sorted(order.thenComparing(r->r.worker().id())).toList();
  return new Page(filtered.stream().skip((long)page*size).limit(size).toList(),filtered.size(),page,size,summary,attention,clock.instant());
 }
 private static boolean eligible(WorkerTelemetryService.View w,String trust,Set<String> languages){return !w.credentialRevoked()&&w.approvalStatus().equals("APPROVED")&&Set.of("ONLINE","BUSY").contains(w.status())&&w.protocolVersion()==1&&(trust.equals("COMMUNITY")?Set.of("TRUSTED","COMMUNITY").contains(w.trustLevel()):w.trustLevel().equals("TRUSTED"))&&w.capabilities()!=null&&w.capabilities().docker()&&w.capabilities().supportedLanguages().containsAll(languages);}
 @Transactional(readOnly=true,isolation=Isolation.REPEATABLE_READ)
 public Object capacity(UUID tournament,UUID group,String trust,int requested){
  if(!Set.of("TRUSTED","COMMUNITY").contains(trust)||requested<1||requested>256)throw new AuthException("INVALID_REMOTE_POLICY",400);
  var t=tournaments.findById(tournament.toString()).orElseThrow(()->new AuthException("TOURNAMENT_NOT_FOUND",404));var g=group==null?null:groups.group(group);Set<String> languages=new TreeSet<>(db.query("select distinct w.language from tournament_bot_submissions s join tournament_submission_versions v on v.id=s.version_id join tournament_code_workspaces w on w.id=v.workspace_id where s.tournament_id=? and s.status='LOCKED'",(r,n)->r.getString(1),tournament));boolean locked=!languages.isEmpty();if(!locked)languages.addAll(t.botPolicy.allowedLanguages());
  var members=g==null?List.<WorkerTelemetryService.View>of():snapshot().stream().filter(w->g.workers().contains(w.id())).toList();var usable=g==null||!g.enabled()?List.<WorkerTelemetryService.View>of():members.stream().filter(w->eligible(w,trust,languages)).toList();int free=usable.stream().mapToInt(WorkerTelemetryService.View::effectiveFreeSlots).sum(),total=usable.stream().mapToInt(WorkerTelemetryService.View::capacityBudget).sum();
  boolean configurable=Set.of(TournamentStatus.DRAFT,TournamentStatus.REGISTRATION).contains(t.status)&&t.matches.isEmpty()&&db.queryForObject("select count(*) from match_execution_jobs where tournament_id=?",Integer.class,tournament)==0;
  return Map.of("groupName",g==null?"":g.name(),"workers",members.size(),"compatibleWorkers",usable.size(),"totalSlots",total,"freeSlots",free,"shortfall",Math.max(0,requested-free),"languages",languages,"languageSource",locked?"LOCKED_SUBMISSIONS":"ALLOWED_LANGUAGES","canConfigure",configurable,"remoteSupported",t.participantPolicy==ParticipantPolicy.BOT_ONLY&&submissions.enabled(t.id));
 }
 @Transactional(readOnly=true) public Object groupCapacity(){var all=snapshot();return groups.list().stream().map(g->{var members=all.stream().filter(w->g.workers().contains(w.id())).toList();var usable=g.enabled()?members.stream().filter(w->eligible(w,"COMMUNITY",Set.of())).toList():List.<WorkerTelemetryService.View>of();var active=db.queryForList("select t.name,t.id,p.minimum_trust from tournament_worker_policies p join tournaments t on t.id=p.tournament_id where p.group_id=? and p.mode='REMOTE_REQUIRED'",g.id());return Map.of("group",g,"totalSlots",usable.stream().mapToInt(WorkerTelemetryService.View::capacityBudget).sum(),"freeSlots",usable.stream().mapToInt(WorkerTelemetryService.View::effectiveFreeSlots).sum(),"onlineWorkers",usable.size(),"tournaments",active);}).toList();}
 @Transactional(readOnly=true) public Object detail(UUID id){var w=snapshot().stream().filter(v->v.id().equals(id)).findFirst().orElseThrow(()->new AuthException("WORKER_NOT_FOUND",404));var jobs=db.queryForList("select a.status,a.claimed_at,j.match_id,t.name tournament_name from match_execution_attempts a join match_execution_jobs j on j.id=a.job_id join tournaments t on t.id=j.tournament_id where a.worker_id=? order by a.claimed_at desc limit 20",id);return Map.of("worker",w,"warnings",warnings(w),"groups",groups.list().stream().filter(g->g.workers().contains(id)).map(WorkerGroupService.Group::name).toList(),"recentJobs",jobs);}
 @Transactional(readOnly=true) public Object tournamentOptions(int page,String search){if(page<0||page>100000||search.length()>100)throw new AuthException("INVALID_FILTER",400);String q="%"+search.strip().toLowerCase(Locale.ROOT).replace("!","!!").replace("%","!%").replace("_","!_")+"%",where=" from tournaments t left join tournament_worker_policies p on p.tournament_id=t.id where t.trashed_at is null and lower(t.name) like ? escape '!'";return Map.of("items",db.queryForList("select t.id,t.name,t.status,t.created_at,p.mode,p.group_id"+where+" order by t.created_at desc,t.id limit 25 offset ?",q,(long)page*25),"total",db.queryForObject("select count(*)"+where,Long.class,q),"page",page,"size",25);}
}
